local FriendMainInfoNode = Class("FriendMainInfoNode")
function FriendMainInfoNode:__init()
    self.countDownEnv = nil
    ---@type UnityEngine.Transform
    self.BtnChat = nil
end

function FriendMainInfoNode:__delete()
    self.countDownEnv = nil
    self.BtnChat = nil
    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function FriendMainInfoNode:SetCallBack(cb)
    self.__callback = cb
end

function FriendMainInfoNode:Awake()
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            self.__callback()
        end
    end
    if isNull(self.CommonPlayerHeadNode.Env) then
        self.CommonPlayerHeadNode:Init()
    end
    self.BtnChat = self.BtnSend.transform.parent:Find("BtnChat")
end

function FriendMainInfoNode:FreshBaseUI(data, func, cellType)
    --刷新基础信息
    --printInfo("====>>"..table.dump(data))
    local isOnline = checkInt(data.isOnline) == 1 or cellType ~= Constants.FriendCellType.FriendList
    self.CommonPlayerHeadNode.Env:FreshAvatarFrame(data.avatar, data.avatarFrame)
    self.CommonPlayerHeadNode.Env:SetCallBack(function()
        -- 点击自己无效
        if checkInt(data.friendId) == checkInt(GameUtils.GetPlayerId()) then
            return
        end
        -- 直接进入 他人的 个人信息界面2D版 
        GameUtils.ShowPlayerInfo(data.friendId, nil)
    end)
    self.CommonPlayerHeadNode.Env:UpdateGrayNode(not isOnline)
    CfUtils.FillText(self.TxtLv, localize("Lv._num_", {_num_ = data.level}))
    CfUtils.FillText(self.TxtPlayerName, data.name)
    --根据cellType来刷新按钮功能
    local isFriendList = cellType == Constants.FriendCellType.FriendList
    local isRequestList = cellType == Constants.FriendCellType.RequestList
    local isRecommendList = cellType == Constants.FriendCellType.RecommendList
    KTool.SetActive(self.ButtonGroup1, isFriendList)
    KTool.SetActive(self.ButtonGroup2, isRequestList)
    KTool.SetActive(self.ButtonGroup3, isRecommendList)
    KTool.SetActive(self.OffLineNode, not isOnline)

    if not isOnline then
        CfUtils.FillText(self.Timer, self:GetOfflineTimeDesc(data.lastExitTime))
    end
    if isFriendList then
        local hasGived = friendComponent:IsGiveGift(data.friendId)
        local hasDrawed = friendComponent:IsDrawGift(data.friendId)
        local isReceive = friendComponent:IsReceiveGift(data.friendId)
        local canDraw = isReceive and (not hasDrawed)
        self:SetBtnGiveGray(hasGived)
        self:SetBtnDrawGray(not canDraw)
        -- 添加一个领取和赠送按钮互斥的逻辑
        KTool.SetActive(self.BtnAccept, canDraw)
        KTool.SetActive(self.BtnSend, not canDraw)
        self:SetBtnPVPGray(not isOnline)
        SetButtonAction(self.BtnSend, function ()
            if cellType == Constants.FriendCellType.FriendList then
                func.give()
            end
        end)
        SetButtonAction(self.BtnAccept, function ()
            if cellType == Constants.FriendCellType.FriendList then
                func.draw()
                KTool.SetActive(self.BtnAccept, false)
                KTool.SetActive(self.BtnSend, true)
            end
        end)
        self:SetPVPCountDown(data.friendId)

        SetButtonAction(self.BtnBattle, function()
            if cellType == Constants.FriendCellType.FriendList and isOnline then
                local isInCD, cd = friendComponent:IsFriendInPVPCountDown(data.friendId)
                if isInCD then
                    GameUtils.Toast(localize("请稍后尝试"))
                else
                    if friendComponent:HasPVPTeam() then
                        -- 如果有编队，发送邀请
                        func.pvp()
                        friendComponent:SetFriendPVPCountDown(data.friendId)
                        self:SetPVPCountDown(data.friendId)
                    else
                        -- 如果没有编队，先去编队
                        GameUtils.Toast(localize("您还没有编队，请先编个队吧"))
                        if not friendComponent:IsInPVPFormation() then
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = Constants.SpecialQuestId.FriendPVPId, teamIndex = 1 } })
                        end
                    end
                end
            else
                GameUtils.Toast(localize("好友不在线，无法发起对战"))
            end
        end)
        if self.BtnChat then
            KTool.SetActive(self.BtnChat.gameObject, true)
            SetButtonAction(self.BtnChat, function()
                if checkNumber(data.friendId) > 0 then
                    local ChatConstants = import('Game.OverseaChat.ChatConstants')
                    UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaChatMainDialog, {type = ChatConstants.Channels.Single, data = data}))
                end
            end)
        end
    elseif isRequestList then
        if self.BtnChat then
            KTool.SetActive(self.BtnChat.gameObject, false)
        end
        SetButtonAction(self.BtnAgree, function ()
            if cellType == Constants.FriendCellType.RequestList then
                func.agree()
            end
        end)
        SetButtonAction(self.BtnRefuse, function ()
            if cellType == Constants.FriendCellType.RequestList then
                func.refuse()
            end
        end)
    elseif isRecommendList then--点击添加后置灰，服务端添加后对应添加上
        local isSendAddReq = friendComponent:IsSendAddReq(data.friendId)--好友请求中
        self:SetBtnAddGray(isSendAddReq)
        SetButtonAction(self.BtnAdd, function ()
            if cellType == Constants.FriendCellType.RecommendList then
                func.add()
            end
        end)
    end
end

---是否置灰赠送体力按钮
---@param isGray boolean 为true时置灰
function FriendMainInfoNode:SetBtnGiveGray(isGray)
    if isNull(isGray) then
        return
    end
    CfUtils.SetUISwitchImage(self.ImgBgSend, isGray and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgIconSend, isGray and 2 or 1)
    CfUtils.SetUISwitchText(self.TxtSend, isGray and 2 or 1)
    --CfUtils.SetCanvasGroupAlpha(self.BtnSend, isGray and 0.4 or 1)
end

---是否置灰领取体力按钮
---@param isGray boolean 为true时置灰
function FriendMainInfoNode:SetBtnDrawGray(isGray)
    if isNull(isGray) then
        return
    end

    CfUtils.SetUISwitchImage(self.ImgBgAccept, isGray and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgIconAccept, isGray and 2 or 1)
    CfUtils.SetUISwitchText(self.TxtAccept, isGray and 2 or 1)
    --CfUtils.SetCanvasGroupAlpha(self.BtnAccept, isGray and 0.4 or 1)
end

---是否置灰邀请PVP按钮
---@param isGray boolean 为true时置灰
function FriendMainInfoNode:SetBtnPVPGray(isGray)
    if isNull(isGray) then
        return
    end
    CfUtils.SetCanvasGroupAlpha(self.BtnBattle.transform.parent.gameObject, isGray and 0.4 or 1)
end

---是否置灰邀请添加好友按钮
---@param isGray boolean 为true时置灰
function FriendMainInfoNode:SetBtnAddGray(isGray)
    if isNull(isGray) then
        return
    end
    local fmt = isGray and "send" or "add"
    CfUtils.FillImage(self.BtnAdd, string.format("UIAtlas/Friend/friend_addfriends_img_%s.png", fmt))
    CfUtils.SetCanvasGroupAlpha(self.BtnAdd, isGray and 0.4 or 1)
end

function FriendMainInfoNode:SetPVPCountDown(friendId)
    local isInCD, cd = friendComponent:IsFriendInPVPCountDown(friendId)
    KTool.SetActive(self.BlackTime, isInCD)
    if isNull(self.countDownEnv) then
        self.countDownEnv = CfUtils.GetLuaScr(self.TextNumber, "Game.Behaviours.CommonCountdownText")
    end
    KTool.SetActive(self.BtnBattle, not isInCD)
    if isInCD then
        self.countDownEnv:StartLeftSecond(cd, 4, function ()
            friendComponent:ClearFriendPVPCountDown(friendId)
            self:SetPVPCountDown(friendId)
        end)
    else
        self.countDownEnv:StopTimer()
    end
end

---传入离线秒数，获取对应的描述
function FriendMainInfoNode:GetOfflineTimeDesc(seconds)
    seconds = checkInt(seconds)
    local desc
    if seconds < 3600 then
        desc = localize("1小时内")
    elseif seconds < 86400 then
        desc = math.floor(seconds/3600)..localize("小时前")
    elseif seconds < 2592000 then
        desc = math.floor(seconds/86400)..localize("天前")
    elseif seconds < 7776000 then
        desc = math.floor(seconds/2592000)..localize("月前")
    elseif seconds >= 7776000 then
        desc = localize("3月以上")
    end
    return desc
end

function FriendMainInfoNode:OnDestroy()
    if not isNull(self.countDownEnv) then
        self.countDownEnv:StopTimer()
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return FriendMainInfoNode